import csv
with open('outputs/t08_pois_clean.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        lat = float(row['latitude'])
        lon = float(row['longitude'])
        if not (-90 <= lat <= 90):
            print(f'Invalid lat: {lat} for {row[\"qid\"]}')
        if not (-180 <= lon <= 180):
            print(f'Invalid lon: {lon} for {row[\"qid\"]}')
print('Validation complete')
